"use client";

import { useActionState, useState } from "react";
import { resetAllData } from "./actions";

export function ResetData() {
  const [state, action, pending] = useActionState(resetAllData, {});
  const [typed, setTyped] = useState("");
  return <section className="rounded-xl border border-danger/40 bg-card p-6">
    <h2 className="text-sm font-medium text-danger">Danger zone</h2>
    <p className="mt-1 text-sm text-muted-foreground">Reset all data permanently deletes your accounts, transactions, imports, goals, plans, AI conver
    <form action={action} className="mt-4 flex flex-wrap items-end gap-3">
      <label className="grid gap-1.5 text-sm font-medium">Type RESET to confirm
        <input name="confirmation" value={typed} onChange={event => setTyped(event.target.value)} autoComplete="off" spellCheck={false}
          className="min-h-10 rounded-lg border border-border bg-card px-3 py-2 text-sm font-normal text-foreground" />
      </label>
      <button disabled={typed !== "RESET" || pending} className="min-h-10 rounded-lg bg-danger px-4 py-2 text-sm font-medium text-background disabled:
        {pending ? "Resetting…" : "Reset all data"}
      </button>
    </form>
    {state.error && <p role="alert" className="mt-3 text-sm text-danger">{state.error}</p>}
  </section>;
}
// The values Moneo needs before it can reach its database, so they can't live in it. `npm run
// setup` writes them to .env; this only shows whether each is present, never the value.
const ITEMS = [
  ["Database and services", ["SUPABASE_DB_URL", "SUPABASE_SERVICE_ROLE_KEY", "NEXT_PUBLIC_SUPABASE_URL"]],
  ["Automatic owner sign-in", ["MONEO_OWNER_EMAIL", "MONEO_OWNER_PASSWORD"]],
  ["Encryption for saved keys and bank sessions", ["BANK_TOKEN_ENCRYPTION_KEY"]],
  ["Background jobs", ["CRON_SECRET"]],
