import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { expect, test } from "@playwright/test";

// One-off driver: real Tailscale, QA session only, test server on port 3100 with no owner login.
const S = "C:/Users/mgsuk/AppData/Local/Temp/claude/e4b9319d8f659e7e/960c24e5-426c-4270-afc6-2ee88b69ffac/scratchpad";
const HOST = "indkhan.tail75323a.ts.net";
const state = JSON.parse(readFileSync("C:/Users/mgsuk/.t3/worktrees/Moneo/t3-ebb24ccb/e2e/.auth.json", "utf8"));
const serve = () => execFileSync("C:/Program Files/Tailscale/tailscale.exe", ["serve", "status", "--json"], { encoding: "utf8" });
const log = (...a: unknown[]) => console.log("RESULT", ...a);
test.setTimeout(180_000);
test.describe.configure({ mode: "serial" });

test("1 laptop: Turn on", async ({ browser }) => {
  const context = await browser.newContext({ storageState: state, baseURL: "http://localhost:3100" });
  const page = await context.newPage();
  await page.goto("/settings#phone");
  const card = page.getByRole("region", { name: /Phone and tablet/ });
  await card.getByRole("button", { name: "Turn on" }).click();
  await expect(card.getByRole("button", { name: "Turn off" })).toBeVisible({ timeout: 40_000 });
  log("on:", (await card.innerText()).replace(/\s+/g, " "));
  log("serve:", serve().replace(/\s+/g, ""));
  await card.screenshot({ path: `${S}/card-on-light.png` });
  await context.close();
});

test("2 phone-size browser through the real ts.net address", async ({ browser }) => {
  const remote = { ...state, cookies: state.cookies.map((c: Record<string, unknown>) => ({ ...c, domain: HOST, secure: true })) };
  const context = await browser.newContext({ storageState: remote, baseURL: `https://${HOST}`, viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, colorScheme: "dark" });
  const page = await context.newPage();
  const browserToStorage: string[] = [];
  page.on("request", r => { if (/127\.0\.0\.1|localhost/.test(r.url())) browserToStorage.push(r.url()); });

  for (const path of ["/", "/money", "/plan", "/insights", "/import", "/settings"]) {
    const start = Date.now();
    const response = await page.goto(path);
    log(path, response?.status(), `${Date.now() - start}ms`, new URL(page.url()).host);
    expect(response?.status()).toBe(200);
  }

  // A server action through Tailscale, and the ChatGPT message.
  await page.goto("/settings");
  await page.getByRole("button", { name: "Sign in with ChatGPT" }).click();
  await expect(page.getByText(/ChatGPT sign-in can only return/)).toBeVisible({ timeout: 20_000 });
  log("chatgpt:", new URL(page.url()).host, await page.getByText(/ChatGPT sign-in can only return/).innerText());

  // Bank and Scalable from the device.
  for (const route of ["/api/bank/connect", "/api/scalable/connect"]) {
    const response = await context.request.post(route, { data: { aspspName: "x", country: "DE" } });
    log(route, response.status(), (await response.json()).error);
    expect(response.status()).toBe(409);
  }

  // An attachment uploaded and opened from the device.
  const png = Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==", "base64");
  const uploaded = await context.request.post("/api/chat/attachments", { multipart: { file: { name: "synthetic.png", mimeType: "image/png", buffer: png } } });
  expect(uploaded.status()).toBe(200);
  const { path } = await uploaded.json();
  const opened = await context.request.get(`/api/chat/attachments?${new URLSearchParams({ path })}`, { maxRedirects: 0 });
  log("attachment:", opened.status(), opened.headers()["content-type"], (await opened.body()).length === png.length);
  expect(opened.status()).toBe(200);
  expect((await opened.body()).equals(png)).toBe(true);

  // Secure context, so the microphone is allowed.
  log("secure context:", await page.evaluate(() => window.isSecureContext), "mediaDevices:", await page.evaluate(() => Boolean(navigator.mediaDevices?.getUserMedia)));
  log("manifest:", JSON.stringify((await (await context.request.get("/manifest.webmanifest")).json()).display), (await (await context.request.get("/manifest.webmanifest")).text()).includes("orientation"));

  await page.goto("/settings#phone");
  const card = page.getByRole("region", { name: /Phone and tablet/ });
  await card.scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${S}/card-on-phone-dark.png` });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  log("horizontal overflow:", overflow);
  log("browser requests to loopback:", browserToStorage);
  expect(browserToStorage).toEqual([]);
  await context.close();
});

test("3 no session through ts.net gets no data", async ({ browser }) => {
  const context = await browser.newContext({ baseURL: `https://${HOST}` });
  const response = await context.request.get("/api/conversations");
  log("no session:", response.status());
  expect(response.status()).toBe(401);
  await context.close();
});

test("4 laptop: Turn off removes only the forward", async ({ browser }) => {
  const context = await browser.newContext({ storageState: state, baseURL: "http://localhost:3100" });
  const page = await context.newPage();
  page.on("dialog", dialog => dialog.accept());
  await page.goto("/settings#phone");
  const card = page.getByRole("region", { name: /Phone and tablet/ });
  await card.getByRole("button", { name: "Turn off" }).click();
  await expect(card.getByRole("button", { name: "Turn on" })).toBeVisible({ timeout: 30_000 });
  log("off:", (await card.innerText()).replace(/\s+/g, " "));
  log("serve:", serve().replace(/\s+/g, ""));
  await context.close();
});

