import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, expect, it, vi } from "vitest";
import { PhoneAccessCard } from "./phone-access-card";

vi.mock("./phone-access-actions", () => ({ turnOn: vi.fn(), turnOff: vi.fn() }));
afterEach(cleanup);

it("stays one line and a button until the owner asks for it", () => {
  render(<PhoneAccessCard initial={{ state: "off" }} />);
  expect(screen.getByRole("button", { name: "Turn on" })).toBeTruthy();
  expect(screen.queryByRole("link")).toBeNull();
  expect(screen.queryByRole("img")).toBeNull();
});

it("shows only the step that is missing", () => {
  render(<PhoneAccessCard initial={{ state: "needs_approval", link: "https://login.tailscale.com/f/serve?node=abc" }} />);
  expect(screen.getByRole("link", { name: "Allow secure addresses in Tailscale" }).getAttribute("href")).toBe("https://login.tailscale.com/f/serve?node=abc");
  expect(screen.getByRole("button", { name: "Check again" })).toBeTruthy();
});

it("shows the address and scan code once on", () => {
  render(<PhoneAccessCard initial={{ state: "on", url: "https://pc.example.ts.net", qr: "<svg></svg>" }} />);
  expect(screen.getByRole("img", { name: "Scan code for https://pc.example.ts.net" })).toBeTruthy();
  expect(screen.getByRole("link", { name: "https://pc.example.ts.net" })).toBeTruthy();
  expect(screen.getByRole("button", { name: "Turn off" })).toBeTruthy();
});

