.code .k { color: var(--ai); } .code .s { color: var(--brand); } .code .c { color: var(--muted-fg); } .code .n { color: var(--warn); }
.grid { display: grid; gap: 18px; }
.g2 { grid-template-columns: 1fr 1fr; } .g3 { grid-template-columns: repeat(3, 1fr); } .g5 { grid-template-columns: repeat(5, 1fr); }
.big { font: 600 44px/1 var(--display); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.tag-line { margin-top: auto; font: 500 22px/1.35 var(--display); letter-spacing: -.01em; border-left: 4px solid var(--brand); padding: 4px 0 4px 18px; }
.tag-line span { color: var(--muted-fg); }
ul.ticks { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
ul.ticks li { padding-left: 28px; position: relative; font-size: 16px; }
ul.ticks li::before { content: ""; position: absolute; left: 2px; top: 6px; width: 14px; height: 14px; border-radius: 5px; background: var(--brand-soft); border: 1.5px solid var(--brand); }
ul.ticks.x li::before { background: var(--danger-soft); border-color: var(--danger); }

/* Scene 1 */
.hero { display: grid; grid-template-columns: 1.15fr 1fr; gap: 40px; align-items: center; flex: 1; }
.stack-tags { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 34px; }
.stack-tags span { font: 500 13px var(--mono); border: 1px solid var(--border); background: var(--card); padding: 6px 12px; border-radius: 99px; color: var(--muted-fg); }
.mock { position: relative; height: 560px; }
.mock .card { position: absolute; }
.slider { height: 6px; border-radius: 9px; background: var(--muted); position: relative; margin: 14px 0 6px; }
.slider i { position: absolute; left: 0; top: 0; bottom: 0; width: 46%; border-radius: 9px; background: var(--brand); }
.slider b { position: absolute; left: 46%; top: 50%; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; background: var(--card); border: 2px solid var(--brand); }
.example { position: absolute; right: 0; bottom: -6px; font: 500 11px var(--mono); color: var(--muted-fg); letter-spacing: .08em; text-transform: uppercase; }

/* Diagrams */
.diagram { position: relative; flex: 1; }
.node { position: absolute; background: var(--card); border: 1px solid var(--border); border-radius: 18px; padding: 16px 18px; box-shadow: var(--shadow); }
.node h4 { margin: 0 0 4px; font: 600 19px/1.2 var(--display); letter-spacing: -.01em; }
.node p { margin: 0; font-size: 14px; color: var(--muted-fg); line-height: 1.45; }
.node .mono { font-size: 12.5px; color: var(--muted-fg); display: block; margin-top: 8px; line-height: 1.55; }
.node.ai { border-color: var(--ai-border); }
.node.hl { border-color: var(--brand); }
.lane { position: absolute; left: 0; font: 500 12px var(--mono); letter-spacing: .12em; text-transform: uppercase; color: var(--muted-fg); display: flex; align-items: center; gap: 10px; }
.lane::after { content: ""; width: 1100px; height: 1px; background: var(--border); }
