svg.wires path.brand { stroke: var(--brand); }
svg.wires path.danger { stroke: var(--danger); stroke-dasharray: 6 6; }
svg.wires text { font: 500 12px var(--mono); fill: var(--muted-fg); }

/* Sandbox nesting */
.nest { border: 1.5px solid var(--border); border-radius: 22px; padding: 18px 20px 20px; background: var(--card); }
.nest .nest { background: var(--bg); margin-top: 14px; }
.nest .nest .nest { background: var(--card); border-color: var(--brand); border-width: 2px; }
.nest-title { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.nest-title h4 { margin: 0; font: 600 18px var(--display); }
.nest-title code { font-size: 12.5px; color: var(--muted-fg); }
.hdr { font: 12.5px/1.6 var(--mono); color: var(--muted-fg); margin-top: 8px; }
