.exits { display: grid; gap: 9px; }
.exit { display: grid; grid-template-columns: 1.05fr 1.25fr; gap: 14px; align-items: center; background: var(--card); border: 1px solid var(--border); border-radius: 14px; padding: 11px 14px; }
.exit span:first-child { font: 500 14px var(--mono); text-decoration: line-through; text-decoration-color: var(--danger); text-decoration-thickness: 2px; }
.exit span:last-child { font-size: 14px; color: var(--muted-fg); }

/* Pipeline row */
.pipe { display: flex; align-items: stretch; gap: 0; }
.pipe .card { flex: 1; padding: 18px; }
.pipe .arrow { width: 34px; flex: none; display: grid; place-items: center; color: var(--muted-fg); font-size: 22px; }
