<script>
const scenes = [...document.querySelectorAll(".scene")];
const rail = document.querySelector(".rail");
let index = 0;

scenes.forEach((s, i) => {
  const b = document.createElement("button");
  b.innerHTML = `<b>${String(i + 1).padStart(2, "0")}</b>${s.dataset.short}`;
  b.onclick = () => go(i);
  rail.append(b);
});

// One page per scene: everything on it fades in by itself, in its data-s order, so only a scene change needs a key.
function render() {
  scenes.forEach((s, i) => s.classList.toggle("on", i === index));
  const s = scenes[index];
  const parts = [...s.querySelectorAll("[data-s]")];
  parts.forEach(e => { e.classList.remove("shown"); e.style.transitionDelay = `${(+e.dataset.s - 1) * 90}ms`; });
  requestAnimationFrame(() => requestAnimationFrame(() => parts.forEach(e => e.classList.add("shown"))));
  [...rail.querySelectorAll("button")].forEach((b, i) => b.setAttribute("aria-current", i === index));
  document.getElementById("crumb").innerHTML = `<strong>${String(index + 1).padStart(2, "0")}</strong> / ${scenes.length} · ${s.dataset.title}`;
  document.getElementById("bar").style.width = `${((index + 1) / scenes.length) * 100}%`;
  try { history.replaceState(null, "", `#${index + 1}`); } catch {}
}
function go(i) { index = Math.max(0, Math.min(scenes.length - 1, i)); render(); }
function next() { if (index < scenes.length - 1) go(index + 1); }
function prev() { if (index > 0) go(index - 1); }

addEventListener("keydown", e => {
  if (["ArrowRight", "PageDown", " ", "Enter"].includes(e.key)) { e.preventDefault(); next(); }
  else if (["ArrowLeft", "PageUp", "Backspace"].includes(e.key)) { e.preventDefault(); prev(); }
  else if (e.key === "Home") go(0);
  else if (e.key === "End") go(scenes.length - 1);
  else if (e.key.toLowerCase() === "d") setTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark");
  else if (e.key.toLowerCase() === "f") document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen?.();
  else if (e.key.toLowerCase() === "r") document.body.classList.toggle("hide-rail");
});
document.querySelector(".scenes").addEventListener("click", e => { if (!e.target.closest("button,a")) next(); });

function setTheme(t) { document.documentElement.dataset.theme = t; try { localStorage.setItem("moneo-deep-dive-theme", t); } catch {} }
let saved = null; try { saved = localStorage.getItem("moneo-deep-dive-theme"); } catch {}
setTheme(saved || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"));

function fit() {
  const k = Math.min(innerWidth / 1600, innerHeight / 900);
  document.getElementById("stage").style.transform = `translate(-50%, -50%) scale(${k})`;
}
addEventListener("resize", fit); fit();

const m = /^#(\d+)/.exec(location.hash);
go(m ? +m[1] - 1 : 0);
</script>
</body>
</html>

