test("scenes fit", async ({ browser }) => {
  test.setTimeout(120_000);
  for (const scheme of ["light", "dark"] as const) {
    const page = await (await browser.newContext({ viewport: { width: 1600, height: 900 }, colorScheme: scheme })).newPage();
    page.on("pageerror", e => console.log("PAGEERROR", e.message));
    for (let i = 1; i <= 10; i++) {
      await page.goto(`${URL_}#${i}`);
