        const box = document.querySelector(".scenes")!.getBoundingClientRect();
        const scene = document.querySelector(".scene.on")!;
        const out: string[] = [];
        for (const el of scene.querySelectorAll("*")) {
          const r = el.getBoundingClientRect();
          if (r.width && (r.bottom > box.bottom - 8 || r.right > box.right - 8)) out.push(`${el.tagName}.${el.getAttribute("class") ?? ""} b=${Math.round(r.bottom - box.bottom)} r=${Math.round(r.right - box.right)}`);
