        return out.slice(0, 4);
      });
      if (over.length) console.log(scheme, "scene", i, over.join(" | "));
      if (scheme === "light" || i === 2) await page.screenshot({ path: `${S}/s${i}-${scheme}.png` });
    }
  }
  console.log("done");
});

