export async function turnOffPhoneAccess(): Promise<PhoneAccess> {
  if ((await phoneAccess()).state === "on") {
    const off = await run(["serve", "--https=443", "off"]);
    if (!off.ok) throw reason(off.output);
  }
  return phoneAccess();
}

