import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { expect, test } from "@playwright/test";

// One-off driver, deleted after the run: real Tailscale, QA workspace, test server on port 3100.
const HOST = "indkhan.tail75323a.ts.net";
const state = JSON.parse(readFileSync("e2e/.auth.json", "utf8"));
const remote = { ...state, cookies: state.cookies.map((c: Record<string, unknown>) => ({ ...c, domain: HOST, secure: true })) };
const serve = () => execFileSync("C:/Program Files/Tailscale/tailscale.exe", ["serve", "status", "--json"], { encoding: "utf8" }).replace(/\s+/g, "");
const log = (...a: unknown[]) => console.log("RESULT", ...a);
const api = process.env.NEXT_PUBLIC_SUPABASE_URL!, key = process.env.SUPABASE_SERVICE_ROLE_KEY!;
const headers = { apikey: key, authorization: `Bearer ${key}`, "content-type": "application/json", prefer: "return=representation" };
const HTML = '<html><head><script src="https://cdn.jsdelivr.net/npm/echarts@5.5.0/dist/echarts.min.js"></script></head><body><p id="r">pending</p><script>document.getElementById("r").textContent=typeof echarts</script></body></html>';

test("charts, then turning off from the phone", async ({ browser }) => {
  test.setTimeout(120_000);
  const users = (await (await fetch(`${api}/auth/v1/admin/users?per_page=200`, { headers })).json()).users as { id: string; email: string }[];
  const owner = users.find(u => u.email === process.env.E2E_USER_EMAIL)!.id;
  const workspace = (await (await fetch(`${api}/rest/v1/workspaces?owner_id=eq.${owner}&select=id`, { headers })).json())[0].id;
  const artifact = (await (await fetch(`${api}/rest/v1/artifacts`, { method: "POST", headers, body: JSON.stringify({ workspace_id: workspace, title: "Phone chart check" }) })).json())[0].id;
  try {
    await fetch(`${api}/rest/v1/artifact_versions`, { method: "POST", headers, body: JSON.stringify({ workspace_id: workspace, artifact_id: artifact, version: 1, prompt: "synthetic", html: HTML }) });

    const laptop = await browser.newContext({ storageState: state, baseURL: "http://localhost:3100" });
    const lp = await laptop.newPage();
    await lp.goto("/settings#phone");
    await lp.getByRole("region", { name: /Phone and tablet/ }).getByRole("button", { name: "Turn on" }).click();
    await expect(lp.getByRole("region", { name: /Phone and tablet/ }).getByRole("button", { name: "Turn off" })).toBeVisible({ timeout: 40_000 });
    log("on:", serve());
    await lp.goto(`/ai/artifacts/${artifact}/frame`);
    const laptopChart = lp.frames()[1].locator("#r");
    await expect(laptopChart).toHaveText("object");
    log("laptop chart library:", await laptopChart.textContent());

    const phone = await browser.newContext({ storageState: remote, baseURL: `https://${HOST}`, viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
    const pp = await phone.newPage();
    pp.on("dialog", dialog => dialog.accept());
    const frame = await pp.goto(`/ai/artifacts/${artifact}/frame`);
    log("csp names:", /script-src[^;]*|frame-src[^;]*/.exec(frame!.headers()["content-security-policy"] ?? "")?.[0], "| doc has ts.net lib:", (await frame!.text()).includes(`https://${HOST}/artifact-lib/echarts.min.js`));
    const phoneChart = pp.frames()[1].locator("#r");
    await expect(phoneChart).toHaveText("object");
    log("phone chart library:", await phoneChart.textContent());

    await pp.goto("/settings#phone");
    const card = pp.getByRole("region", { name: /Phone and tablet/ });
    await card.getByRole("button", { name: "Turn off" }).click();
    await expect(card.getByRole("button", { name: /Turn on|Turn off|Check again/ })).toBeEnabled({ timeout: 30_000 });
    await expect(card.getByRole("button", { name: "Checking…" })).toHaveCount(0);
    log("phone after turn off:", (await card.innerText()).replace(/\s+/g, " ").slice(0, 300));
    log("error page shown:", await pp.getByText(/something went wrong/i).count());
    log("serve:", serve());
    await lp.goto("/settings#phone");
    log("laptop card:", (await lp.getByRole("region", { name: /Phone and tablet/ }).innerText()).replace(/\s+/g, " "));
  } finally {
    await fetch(`${api}/rest/v1/artifacts?id=eq.${artifact}`, { method: "DELETE", headers });
  }
});

