import { pathToFileURL } from "node:url";
import { resolve } from "node:path";
import { test } from "@playwright/test";

const S = "C:/Users/mgsuk/AppData/Local/Temp/claude/e4b9319d8f659e7e/960c24e5-426c-4270-afc6-2ee88b69ffac/scratchpad";
const URL_ = pathToFileURL(resolve("docs/phone-access-deep-dive.html")).href;

test("scenes fit", async ({ browser }) => {
  test.setTimeout(120_000);
  for (const scheme of ["light", "dark"] as const) {
    const page = await (await browser.newContext({ viewport: { width: 1600, height: 900 }, colorScheme: scheme })).newPage();
    page.on("pageerror", e => console.log("PAGEERROR", e.message));
    for (let i = 1; i <= 10; i++) {
      await page.goto(`${URL_}#${i}`);
      await page.reload();
      await page.waitForTimeout(1100);
      const over = await page.evaluate(() => {
        const box = document.querySelector(".scenes")!.getBoundingClientRect();
        const out: string[] = [];
        for (const el of document.querySelector(".scene.on")!.querySelectorAll("*")) {
          const r = el.getBoundingClientRect();
          if (r.width && (r.bottom > box.bottom - 8 || r.right > box.right - 8)) out.push(`${el.tagName} b=${Math.round(r.bottom - box.bottom)} r=${Math.round(r.right - box.right)}`);
        }
        return out.slice(0, 4);
      });
      if (over.length) console.log(scheme, "scene", i, over.join(" | "));
      await page.screenshot({ path: `${S}/s${i}-${scheme}.png` });
    }
  }
  console.log("done");
});

